import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import openapiTS, { astToString } from 'openapi-typescript';

export const OPENAPI_PATH = fileURLToPath(new URL('../openapi.json', import.meta.url));
export const SCHEMA_PATH = fileURLToPath(new URL('../src/schema.ts', import.meta.url));

const HEADER =
  '// Generated by openapi-typescript from packages/api-client/openapi.json. Do not edit.\n' +
  '// Regenerate: pnpm --filter @bricomission/api openapi:export\n\n';

/** Renders src/schema.ts from the committed OpenAPI snapshot (deterministic, offline). */
export async function renderSchema(): Promise<string> {
  const document = JSON.parse(readFileSync(OPENAPI_PATH, 'utf8')) as Parameters<typeof openapiTS>[0];
  const ast = await openapiTS(document);
  return HEADER + astToString(ast);
}
